			move.cancelled = true
		end
	end
	table.clear(activeMoves)
	if hrp then
		hrp.AssemblyLinearVelocity = Vector3.zero
		hrp.AssemblyAngularVelocity = Vector3.zero
	end
	clearTweenArrivalHold()
	stopHoverPad()
end
