		ED.headLbl = UIK.text(main, { text = "Global Egg Data & History", style = "body", color = LOG_PAL.accent, pos = UDim2.fromOffset(14, 2), size = UDim2.new(1, -28, 0, 18) })
		ED.headLbl.Font = PANEL_BOLD
