		text(header, { Position = UDim2.new(0, 44, 0, 18), Size = UDim2.new(1, -80, 0, 16), Text = "Find Divine, Eternal and Secret across servers", TextSize = 11, TextColor3 = SUB, Font = Enum.Font.BuilderSans })
