    Idle = "Muted", Off = "Muted", Stopped = "Muted", Running = "Good", Active = "Good", On = "Good", Done = "Good",
    Busy = "Info", Travel = "Info", Waiting = "Warn", Warn = "Warn", Error = "Bad", Failed = "Bad",
} }
Config.Widget.Stat = { Size = 26, MinWindow = 10, Speed = 9 }
